  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` bigint(20) unsigned NOT NULL,
  `receipt_number` varchar(40) NOT NULL,
  `printed_at` datetime DEFAULT NULL,
  `printed_by` bigint(20) unsigned DEFAULT NULL,
  `is_void` tinyint(1) NOT NULL DEFAULT 0,
  `voided_at` datetime DEFAULT NULL,
  `voided_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payin_receipts_number` (`receipt_number`),
  UNIQUE KEY `uq_payin_receipts_transaction` (`transaction_id`),
  KEY `fk_payin_receipts_printed_by` (`printed_by`),
  KEY `fk_payin_receipts_voided_by` (`voided_by`),
  CONSTRAINT `fk_payin_receipts_printed_by` FOREIGN KEY (`printed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payin_receipts_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions_x` (`id`),
  CONSTRAINT `fk_payin_receipts_voided_by` FOREIGN KEY (`voided_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `payment_lines`;
CREATE TABLE `payment_lines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` bigint(20) unsigned NOT NULL,
  `line_no` int(10) unsigned NOT NULL,
  `payment_method` enum('cash','cheque','card','online_transfer','bank_deposit','other') NOT NULL,
  `amount` decimal(14,2) NOT NULL,
  `currency_code` char(3) NOT NULL DEFAULT 'BZD',
  `cheque_number` varchar(60) DEFAULT NULL,
  `cheque_bank_name` varchar(150) DEFAULT NULL,
  `cheque_account_name` varchar(180) DEFAULT NULL,
  `card_last4` varchar(10) DEFAULT NULL,
  `card_reference` varchar(100) DEFAULT NULL,
  `online_reference` varchar(100) DEFAULT NULL,
  `machine_reference` varchar(100) DEFAULT NULL,
  `deposited_to_bank_account_id` bigint(20) unsigned DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payment_lines_transaction_line` (`transaction_id`,`line_no`),
  KEY `idx_payment_lines_method` (`payment_method`),
  KEY `idx_payment_lines_bank_account` (`deposited_to_bank_account_id`),
  KEY `idx_payment_lines_transaction_method` (`transaction_id`,`payment_method`),
  CONSTRAINT `fk_payment_lines_bank_account` FOREIGN KEY (`deposited_to_bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `fk_payment_lines_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions_x` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pay_ins`;
CREATE TABLE `pay_ins` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pay_in_id` varchar(20) NOT NULL,
  `department_id` int(10) unsigned DEFAULT NULL,
  `department_name` varchar(255) DEFAULT NULL,
  `cashier_uid` int(10) unsigned NOT NULL,
  `pay_in_date` date NOT NULL,
  `total_cash` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_cheques` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `bank_slip_path` varchar(500) DEFAULT NULL,
  `status` enum('submitted','verified','rejected') NOT NULL DEFAULT 'submitted',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pay_in_id` (`pay_in_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pay_in_cash`;
CREATE TABLE `pay_in_cash` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pay_in_id` varchar(20) NOT NULL,
  `d_100` int(10) unsigned NOT NULL DEFAULT 0,
  `d_50` int(10) unsigned NOT NULL DEFAULT 0,
  `d_20` int(10) unsigned NOT NULL DEFAULT 0,
  `d_10` int(10) unsigned NOT NULL DEFAULT 0,
  `d_5` int(10) unsigned NOT NULL DEFAULT 0,
  `d_2` int(10) unsigned NOT NULL DEFAULT 0,
  `d_1` int(10) unsigned NOT NULL DEFAULT 0,
  `c_50` int(10) unsigned NOT NULL DEFAULT 0,
  `c_25` int(10) unsigned NOT NULL DEFAULT 0,
  `c_10` int(10) unsigned NOT NULL DEFAULT 0,
  `c_5` int(10) unsigned NOT NULL DEFAULT 0,
  `c_1` int(10) unsigned NOT NULL DEFAULT 0,
  `cash_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id`),
  KEY `fk_pic_pay_in` (`pay_in_id`),
  CONSTRAINT `fk_pic_pay_in` FOREIGN KEY (`pay_in_id`) REFERENCES `pay_ins` (`pay_in_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pay_in_cheques`;
CREATE TABLE `pay_in_cheques` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pay_in_id` varchar(20) NOT NULL,
  `bank_name` varchar(150) NOT NULL,
  `cheque_number` varchar(50) NOT NULL,
  `amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id`),
  KEY `fk_pich_pay_in` (`pay_in_id`),
  CONSTRAINT `fk_pich_pay_in` FOREIGN KEY (`pay_in_id`) REFERENCES `pay_ins` (`pay_in_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(120) NOT NULL,
  `name` varchar(150) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `module` varchar(80) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_permissions_code` (`code`),
  KEY `idx_permissions_module` (`module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pos_bank_balances`;
CREATE TABLE `pos_bank_balances` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `bb_uuid` varchar(36) NOT NULL,
  `shift_id` varchar(12) NOT NULL,
  `departmentId` int(10) unsigned DEFAULT NULL,
  `bankId` int(10) unsigned DEFAULT NULL,
  `balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `startingCash` decimal(15,2) NOT NULL DEFAULT 0.00,
  `uid` int(10) unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bb_uuid` (`bb_uuid`),
  KEY `idx_shift_id` (`shift_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pos_cart_items`;
CREATE TABLE `pos_cart_items` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) NOT NULL,
  `shift_id` varchar(36) NOT NULL,
  `uid` int(10) unsigned NOT NULL,
  `customer_id` int(10) unsigned DEFAULT NULL,
  `customer_name` varchar(255) DEFAULT NULL,
  `dept_id` int(10) unsigned DEFAULT NULL,
  `dept_name` varchar(255) DEFAULT NULL,
  `activity_id` int(10) unsigned NOT NULL,
  `activity_name` varchar(255) NOT NULL,
  `activity_code` varchar(50) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `payment_method` varchar(50) NOT NULL,
  `payment_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payment_details`)),
  `beneficiary_name` varchar(255) DEFAULT NULL,
  `status` enum('pending','completed','voided') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pos_service_favorites`;
CREATE TABLE `pos_service_favorites` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uid` int(10) unsigned NOT NULL,
  `activity_id` int(10) unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_uid_activity` (`uid`,`activity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pos_shifts`;
CREATE TABLE `pos_shifts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `shift_id` varchar(12) NOT NULL,
  `uid` int(10) unsigned NOT NULL,
  `department_id` int(10) unsigned DEFAULT NULL,
  `register_id` int(10) unsigned DEFAULT NULL,
  `starting_cash` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `ended_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_shift_id` (`shift_id`),
  KEY `idx_uid_status` (`uid`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `pos_transactions`;
CREATE TABLE `pos_transactions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(32) NOT NULL,
  `shift_id` varchar(12) NOT NULL,
  `uid` int(10) unsigned NOT NULL,
  `customer_id` int(10) unsigned DEFAULT NULL,
  `customer_name` varchar(255) DEFAULT NULL,
  `dept_id` int(10) unsigned DEFAULT NULL,
  `dept_name` varchar(255) DEFAULT NULL,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `items` longtext DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'completed',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_uuid` (`uuid`),
  KEY `idx_shift_id` (`shift_id`),
  KEY `idx_uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `registers`;
CREATE TABLE `registers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `department_id` bigint(20) unsigned NOT NULL,
  `sub_treasury_id` bigint(20) unsigned DEFAULT NULL,
  `register_code` varchar(50) NOT NULL,
  `register_name` varchar(150) NOT NULL,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `uq_registers_code` (`register_code`),
  KEY `fk_registers_department` (`department_id`),
  KEY `fk_registers_sub_treasury` (`sub_treasury_id`),
  CONSTRAINT `fk_registers_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `fk_registers_sub_treasury` FOREIGN KEY (`sub_treasury_id`) REFERENCES `sub_treasuries` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `register_bank_accounts`;
CREATE TABLE `register_bank_accounts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `register_id` bigint(20) unsigned NOT NULL,
  `bank_account_id` bigint(20) unsigned NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_register_bank` (`register_id`,`bank_account_id`),
  KEY `fk_rba_bank_account` (`bank_account_id`),
  CONSTRAINT `fk_rba_bank_account` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `fk_rba_register` FOREIGN KEY (`register_id`) REFERENCES `registers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `register_users`;
CREATE TABLE `register_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `register_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `assigned_by` int(11) DEFAULT NULL,
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_register_user` (`register_id`,`user_id`),
  KEY `idx_ru_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(80) NOT NULL,
  `name` varchar(120) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_roles_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `role_permissions`;
CREATE TABLE `role_permissions` (
  `role_id` bigint(20) unsigned NOT NULL,
  `permission_id` bigint(20) unsigned NOT NULL,
  `granted_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`role_id`,`permission_id`),
  KEY `fk_role_permissions_permission` (`permission_id`),
  CONSTRAINT `fk_role_permissions_permission` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`),
  CONSTRAINT `fk_role_permissions_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `service_favorites`;
CREATE TABLE `service_favorites` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uid` int(10) unsigned NOT NULL,
  `activity_id` int(10) unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_user_activity` (`uid`,`activity_id`),
  KEY `idx_uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `shifts`;
CREATE TABLE `shifts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `shift_id` varchar(36) NOT NULL,
  `uid` int(10) unsigned NOT NULL,
  `department_id` int(10) unsigned DEFAULT NULL,
  `register_id` int(10) unsigned DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=active, 0=ended',
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `ended_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_shift_id` (`shift_id`),
  KEY `idx_uid_status` (`uid`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sub_treasuries`;
CREATE TABLE `sub_treasuries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `department_id` bigint(20) unsigned NOT NULL,
  `sub_treasury_code` varchar(50) NOT NULL,
  `sub_treasury_name` varchar(150) NOT NULL,
  `district` varchar(100) DEFAULT NULL,
  `address_line` varchar(255) DEFAULT NULL,
  `contact_phone` varchar(50) DEFAULT NULL,
  `contact_email` varchar(150) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `uq_sub_treasuries_code` (`sub_treasury_code`),
  KEY `fk_sub_treasuries_department` (`department_id`),
  CONSTRAINT `fk_sub_treasuries_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sub_treasury_bank_accounts`;
CREATE TABLE `sub_treasury_bank_accounts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sub_treasury_id` bigint(20) unsigned NOT NULL,
  `bank_account_id` bigint(20) unsigned NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_treasury_bank` (`sub_treasury_id`,`bank_account_id`),
  KEY `fk_stba_bank_account` (`bank_account_id`),
  CONSTRAINT `fk_stba_bank_account` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `fk_stba_sub_treasury` FOREIGN KEY (`sub_treasury_id`) REFERENCES `sub_treasuries` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `suppliers`;
CREATE TABLE `suppliers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `supplier_name` varchar(200) NOT NULL,
  `contact_name` varchar(150) DEFAULT NULL,
  `tax_id` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `address_line_1` varchar(255) DEFAULT NULL,
  `address_line_2` varchar(255) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `uq_suppliers_name` (`supplier_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `support_tickets`;
CREATE TABLE `support_tickets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `full_name` varchar(150) NOT NULL,
  `email` varchar(150) NOT NULL,
  `category` varchar(100) NOT NULL,
  `priority` enum('normal','high','urgent') NOT NULL DEFAULT 'normal',
  `subject` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `status` enum('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open',
  `resolved_by` bigint(20) unsigned DEFAULT NULL,
  `resolution_notes` text DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_st_user` (`user_id`),
  KEY `fk_st_resolved` (`resolved_by`),
  CONSTRAINT `fk_st_resolved` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_st_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) NOT NULL,
  `shift_id` varchar(36) NOT NULL,
  `uid` int(10) unsigned NOT NULL,
  `customer_id` int(10) unsigned DEFAULT NULL,
  `customer_name` varchar(255) DEFAULT NULL,
  `dept_id` int(10) unsigned DEFAULT NULL,
  `dept_name` varchar(255) DEFAULT NULL,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Array of cart items with payment details' CHECK (json_valid(`items`)),
  `status` enum('completed','voided','refunded') DEFAULT 'completed',
  `completed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_uuid` (`uuid`),
  KEY `idx_shift` (`shift_id`),
  KEY `idx_uid` (`uid`),
  KEY `idx_date` (`completed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `transactions_x`;
CREATE TABLE `transactions_x` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `transaction_number` varchar(40) NOT NULL,
  `receipt_number` varchar(40) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `customer_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned NOT NULL,
  `sub_treasury_id` bigint(20) unsigned DEFAULT NULL,
  `register_id` bigint(20) unsigned DEFAULT NULL,
  `cost_center_id` bigint(20) unsigned DEFAULT NULL,
  `bank_account_id` bigint(20) unsigned DEFAULT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `transaction_date` date NOT NULL,
  `total_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `currency_code` char(3) NOT NULL DEFAULT 'BZD',
  `status` enum('draft','submitted','under_review','approved','posted','rejected','reversed') NOT NULL DEFAULT 'draft',
  `source_channel` enum('counter','online','import','adjustment') NOT NULL DEFAULT 'counter',
  `narration` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) unsigned NOT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `posted_at` datetime DEFAULT NULL,
  `reversed_at` datetime DEFAULT NULL,
  `reversal_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_transactions_uuid` (`uuid`),
  UNIQUE KEY `uq_transactions_number` (`transaction_number`),
  UNIQUE KEY `uq_transactions_receipt` (`receipt_number`),
  KEY `idx_transactions_status_date` (`status`,`transaction_date`),
  KEY `idx_transactions_department` (`department_id`),
  KEY `idx_transactions_customer` (`customer_id`),
  KEY `idx_transactions_user` (`user_id`),
  KEY `fk_transactions_cost_center` (`cost_center_id`),
  KEY `fk_transactions_bank_account` (`bank_account_id`),
  KEY `fk_transactions_branch` (`branch_id`),
  KEY `fk_transactions_created_by` (`created_by`),
  KEY `fk_transactions_submitted_by` (`submitted_by`),
  KEY `idx_transactions_created_at` (`created_at`),
  KEY `fk_transactions_register` (`register_id`),
  KEY `idx_transactions_location` (`sub_treasury_id`,`register_id`,`transaction_date`),
  CONSTRAINT `fk_transactions_bank_account` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `fk_transactions_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `fk_transactions_cost_center` FOREIGN KEY (`cost_center_id`) REFERENCES `cost_centers` (`id`),
  CONSTRAINT `fk_transactions_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_transactions_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `fk_transactions_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `fk_transactions_register` FOREIGN KEY (`register_id`) REFERENCES `registers` (`id`),
  CONSTRAINT `fk_transactions_sub_treasury` FOREIGN KEY (`sub_treasury_id`) REFERENCES `sub_treasuries` (`id`),
  CONSTRAINT `fk_transactions_submitted_by` FOREIGN KEY (`submitted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_transactions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `transaction_approvals`;
CREATE TABLE `transaction_approvals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` bigint(20) unsigned NOT NULL,
  `approval_step` int(10) unsigned NOT NULL,
  `approver_user_id` bigint(20) unsigned NOT NULL,
  `decision` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `decision_notes` varchar(255) DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_transaction_approval_step` (`transaction_id`,`approval_step`),
  KEY `idx_transaction_approvals_user` (`approver_user_id`),
  CONSTRAINT `fk_transaction_approvals_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions_x` (`id`),
  CONSTRAINT `fk_transaction_approvals_user` FOREIGN KEY (`approver_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `transaction_items`;
CREATE TABLE `transaction_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `transaction_id` bigint(20) unsigned NOT NULL,
  `cost_center_activity_id` bigint(20) unsigned DEFAULT NULL,
  `description` varchar(255) NOT NULL,
  `quantity` decimal(12,2) NOT NULL DEFAULT 1.00,
  `unit_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `line_total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `currency_code` char(3) NOT NULL DEFAULT 'BZD',
  `sort_order` int(11) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_transaction_items_uuid` (`uuid`),
  KEY `idx_transaction_items_transaction` (`transaction_id`),
  KEY `idx_transaction_items_activity` (`cost_center_activity_id`),
  CONSTRAINT `fk_transaction_items_activity` FOREIGN KEY (`cost_center_activity_id`) REFERENCES `cost_center_activities` (`id`),
  CONSTRAINT `fk_transaction_items_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions_x` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `transaction_status_history`;
CREATE TABLE `transaction_status_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` bigint(20) unsigned NOT NULL,
  `previous_status` varchar(50) DEFAULT NULL,
  `new_status` varchar(50) NOT NULL,
  `changed_by` bigint(20) unsigned NOT NULL,
  `change_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_transaction_status_history_transaction` (`transaction_id`),
  KEY `fk_transaction_status_history_user` (`changed_by`),
  CONSTRAINT `fk_transaction_status_history_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions_x` (`id`),
  CONSTRAINT `fk_transaction_status_history_user` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `user_type` enum('internal','external') NOT NULL,
  `auth_source` enum('local','sso','microsoft') NOT NULL DEFAULT 'local',
  `username` varchar(100) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `first_name` varchar(100) NOT NULL,
  `last_name` varchar(100) NOT NULL,
  `password_hash` varchar(255) DEFAULT NULL,
  `email_verified_at` datetime DEFAULT NULL,
  `phone_verified_at` datetime DEFAULT NULL,
  `mfa_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `mfa_totp_secret` varchar(64) DEFAULT NULL,
  `mfa_totp_confirmed_at` datetime DEFAULT NULL,
  `status` enum('active','inactive','locked','pending') NOT NULL DEFAULT 'active',
  `failed_login_count` int(10) unsigned NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `profile_image_path` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sub_treasury_id` bigint(20) unsigned DEFAULT NULL,
  `current_session_id` varchar(255) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_uuid` (`uuid`),
  UNIQUE KEY `uq_users_username` (`username`),
  UNIQUE KEY `uq_users_email` (`email`),
  KEY `idx_users_type_status` (`user_type`,`status`),
  KEY `idx_users_department` (`department_id`),
  KEY `idx_users_branch` (`branch_id`),
  KEY `fk_users_created_by` (`created_by`),
  KEY `fk_users_updated_by` (`updated_by`),
  KEY `idx_users_sub_treasury` (`sub_treasury_id`),
  CONSTRAINT `fk_users_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `fk_users_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_users_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `fk_users_sub_treasury` FOREIGN KEY (`sub_treasury_id`) REFERENCES `sub_treasuries` (`id`),
  CONSTRAINT `fk_users_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_roles`;
CREATE TABLE `user_roles` (
  `user_id` bigint(20) unsigned NOT NULL,
  `role_id` bigint(20) unsigned NOT NULL,
  `assigned_by` bigint(20) unsigned DEFAULT NULL,
  `assigned_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`user_id`,`role_id`),
  KEY `fk_user_roles_role` (`role_id`),
  KEY `fk_user_roles_assigned_by` (`assigned_by`),
  CONSTRAINT `fk_user_roles_assigned_by` FOREIGN KEY (`assigned_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_user_roles_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`),
  CONSTRAINT `fk_user_roles_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_sessions`;
CREATE TABLE `user_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `session_token_hash` varchar(255) NOT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `login_method` enum('password','sso','password_mfa') NOT NULL,
  `started_at` datetime NOT NULL DEFAULT current_timestamp(),
  `last_seen_at` datetime NOT NULL DEFAULT current_timestamp(),
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_sessions_token` (`session_token_hash`),
  KEY `idx_user_sessions_user` (`user_id`),
  KEY `idx_user_sessions_expires` (`expires_at`),
  CONSTRAINT `fk_user_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


